function mapDuaCategory(raw: string): DuaCategory {
  switch (raw) {
    case 'Morning Adhkar':
      return 'morning_adhkar';
    case 'Evening Adhkar':
      return 'evening_adhkar';
    case 'Before sleeping':
      return 'sleep';
    case 'After waking':
      return 'waking';
    case 'Before/after eating':
      return 'eating';
    case 'Entering/leaving home':
      return 'home';
    case 'Entering/leaving mosque':
      return 'mosque';
    case 'Travelling':
      return 'travel';
    case 'For parents':
      return 'parents';
    case 'Protection':
      return 'protection';
    case 'Distress & hardship':
      return 'distress';
    case 'Gratitude':
      return 'gratitude';
    case 'Daily routines':
    default:
      return 'daily_routine';
  }
}

